// compose_issue: writes the GitHub issue that records the decision.
//
// Inputs:  $.decision, $.reviewerNotes, $.decidedBy   workflow variables set by whichever branch
//                                                     decided (policy or a human)
//          $.packageRef, $.aiVerdict, $.briefMarkdown, $.workflowId
// Output:  decision ("APPROVED" or "REJECTED"), title, body
//
// Notes on Conductor:
// - The last line calls composeIssue(); what it returns becomes the task output.
//   Everything else is inside the function, because a top-level const or let can fail when
//   Conductor reuses a script context.
// - Text is joined with + because Conductor treats a dollar sign followed by a brace in a
//   task input as a workflow reference, which rules out JavaScript template literals.

function composeIssue() {
  // Link back to the run in the Conductor UI. Change this if you use a different cluster.
  const conductorUi = "https://developer.orkescloud.com";

  // Anything other than an explicit APPROVE is recorded as rejected.
  let decision = "REJECTED";
  if (String($.decision || "").toUpperCase() === "APPROVE") {
    decision = "APPROVED";
  }

  // e.g. "Dependency decision: npm/express@4.17.1 → APPROVED (AI: ADOPT_WITH_CONDITIONS)"
  const title = "Dependency decision: " + $.packageRef + " → " + decision + " (AI: " + $.aiVerdict + ")";

  let notes = "none";
  if ($.reviewerNotes) {
    notes = $.reviewerNotes;
  }

  const body = [
    "## Decision: " + decision,
    "",
    "- **Package:** `" + $.packageRef + "`",
    "- **Decided by:** " + $.decidedBy,
    "- **Reviewer notes:** " + notes,
    "",
    "## AI dependency brief",
    "",
    $.briefMarkdown,
    "",
    "---",
    "Recorded by Orkes Conductor workflow [`" + $.workflowId + "`](" + conductorUi + "/execution/" + $.workflowId + ")."
  ].join("\n");

  return {
    decision: decision,
    title: title,
    body: body
  };
}

composeIssue();
